"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["70418"],{83563(e){e.exports=JSON.parse('{"id":"FIN-202","slug":"scenario-analysis","term":"Scenario Analysis","also_known_as":[],"difficulty":"Intermediate","definition":"Scenario analysis is a planning method that estimates how financial results would change under several different possible futures, such as a base case, an optimistic case and a pessimistic case.","explanation":["The future is uncertain, and a single forecast can give a false sense of certainty. Scenario analysis builds a few coherent stories about how the future might unfold and works out the financial results for each.","Each scenario changes several assumptions together in a way that makes sense. A pessimistic scenario might combine lower sales, falling prices and higher costs, reflecting a recession. An optimistic scenario might combine strong demand, higher prices and a successful product launch.","For example, a company might forecast profit of 5 million in its base case, 8 million in its best case and a loss of 1 million in its worst case. Seeing this range helps managers decide whether a plan is acceptable even if things go badly, and what actions to prepare in case they do.","Scenario analysis differs from sensitivity analysis, which changes one assumption at a time to see its individual effect. The two are often used together to understand risk."],"note":"","total":1500,"prev":{"slug":"scarcity","term":"Scarcity"},"next":{"slug":"seasonality","term":"Seasonality"}}')}}]);